function nextDay(){const r=rates();s.day++;s.gold+=r.gold;s.stone+=r.stone;s.food+=r.food;if(s.goblins>1){s.food-=Math.ceil(s.goblins/3)}s.threat=Math.min(100,s.threat+5);s.raidDone=false;if(s.enemyDefeated){s.enemyHp=40;s.enemyDefeated=false;if(playerMesh){playerMesh.position.set(-2.2,0,1.6);enemyMesh.position.set(1.7,0,-.8)}}log(`Day ${s.day} dawns. Your domain yields ${r.gold} gold and ${r.stone} stone.`);if(s.day%4===0){const power=Math.floor(s.threat*.55)+10,guard=strength();if(guard>=power){s.renown+=8;s.gold+=12;log(`Adventurers repelled (${guard} vs ${power}). The legend of your lair grows.`);notify(`Invasion repelled! +8 renown · +12 gold`)}else{let damage=Math.min(40,power-guard+8);s.hp=Math.max(0,s.hp-damage);s.gold=Math.max(0,s.gold-10);log(`Adventurers breached your halls. Core takes ${damage}% damage.`);notify(`Invasion! Core damaged by ${damage}%. Strengthen your garrison.`)}}if(s.food<0){s.food=0;s.goblins=Math.max(1,s.goblins-1);log('Provisions ran out. A goblin deserted your lair.');}if(s.day%3===0){s.renown+=2;log('Your growing influence earns +2 renown.')}render()}
function endGame(win){$('endNotice').classList.add('show');$('endIcon').textContent=win?'👑':'💔';$('endEyebrow').textContent=win?'THE EMPIRE ENDURES':'THE CORE HAS FALLEN';$('endTitle').textContent=win?'A legend is born.':'The depths grow quiet.';$('endText').textContent=win?`In ${s.day} days, you forged a realm with ${s.renown} renown. The surface will remember the name Understone.`:`Your dungeon held for ${s.day} days and earned ${s.renown} renown. The surface has reclaimed the hollow.`}
$('closeModal').onclick=()=>$('buildModal').classList.remove('open');$('buildModal').onclick=e=>{if(e.target===$('buildModal'))$('buildModal').classList.remove('open')};$('recruitBtn').onclick=recruit;$('raidBtn').onclick=claimSpoils;$('dayBtn').onclick=nextDay;$('restartBtn').onclick=()=>{localStorage.removeItem('understone-save');s=JSON.parse(JSON.stringify(initial));if(playerMesh)playerMesh.position.set(-2.2,0,1.6);if(enemyMesh)enemyMesh.position.set(1.7,0,-.8);$('endNotice').classList.remove('show');render()};$('rosterInfo').onclick=()=>notify(`${s.goblins} goblins · ${strength()} defense strength`);
document.querySelectorAll('.navitem').forEach(b=>b.onclick=()=>{document.querySelectorAll('.navitem').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.nav==='map')document.querySelector('.mapcard').scrollIntoView({behavior:'smooth'});else if(b.dataset.nav==='army')document.querySelector('.rightcol .panel:nth-child(3)').scrollIntoView({behavior:'smooth'});else if(b.dataset.nav==='quests')document.querySelector('.rightcol .panel:first-child').scrollIntoView({behavior:'smooth'})});
render();
})();
</script>

