 if(s.level==null)s.level=1;if(s.xp==null)s.xp=0;if(s.coins==null)s.coins=0;if(s.enemyHp==null)s.enemyHp=40;if(s.enemyDefeated==null)s.enemyDefeated=false;if(s.kills==null)s.kills=0;if(!Array.isArray(s.helpers)||!s.helpers.length)s.helpers=[{id:1,type:'Goblin',level:1,xp:0}];s.helpers=s.helpers.map((h,i)=>({id:h.id??i+1,type:['Goblin','Wizard','Champion'].includes(h.type)?h.type:'Goblin',level:Math.max(1,Math.min(5,Number(h.level)||1)),xp:Math.max(0,Number(h.xp)||0)}));s.nextHelperId=Math.max(Number(s.nextHelperId)||1,...s.helpers.map(h=>(Number(h.id)||0)+1));
