function makeMaterial(color,roughness=.85){return new THREE.MeshStandardMaterial({color,roughness})}
 function buildFighter(color,metal=false){const g=new THREE.Group(),mat=makeMaterial(color),dark=makeMaterial(metal?0x423e38:0x30332d),skin=makeMaterial(metal?0xb6a287:0x87a65f),metalMat=makeMaterial(metal?0x9a8b70:0x596347,.55);const part=(geo,m,x,y,z)=>{const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;g.add(o);return o};part(new THREE.CylinderGeometry(.28,.38,.9,8),mat,0,.92,0);part(new THREE.SphereGeometry(.28,12,10),skin,0,1.58,0);part(new THREE.BoxGeometry(.52,.16,.44),metalMat,0,1.75,0);part(new THREE.BoxGeometry(.12,.12,.1),dark,-.12,1.58,.24);part(new THREE.BoxGeometry(.12,.12,.1),dark,.12,1.58,.24);for(const x of [-.18,.18]){part(new THREE.CylinderGeometry(.1,.12,.58,7),dark,x,.28,0);part(new THREE.BoxGeometry(.16,.12,.32),metalMat,x,.07,.07)}for(const x of [-.37,.37])part(new THREE.CylinderGeometry(.09,.12,.56,7),metalMat,x,1.02,0);if(metal){const shield=part(new THREE.BoxGeometry(.12,.62,.48),metalMat,.52,.9,.13);shield.rotation.z=-.12;const sword=part(new THREE.BoxGeometry(.08,.72,.08),makeMaterial(0xd0c8b3,.25),-.5,.97,.15);sword.rotation.z=.2}else{const staff=part(new THREE.CylinderGeometry(.035,.05,1.2,6),makeMaterial(0x765133),.54,.8,.08);staff.rotation.z=-.15;part(new THREE.SphereGeometry(.12,8,7),makeMaterial(0x82a1bd,.3),.64,1.43,.08)}return g}
 function initArena(){if(!window.THREE)return;try{const canvas=$('dungeon3d');renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputEncoding=THREE.sRGBEncoding;renderer.setClearColor(0x080b0c);scene=new THREE.Scene();scene.background=new THREE.Color(0x090d0e);scene.fog=new THREE.Fog(0x090d0e,11,24);camera=new THREE.PerspectiveCamera(42,1,.1,80);camera.position.set(0,7.2,10.5);camera.lookAt(0,.35,0);scene.add(new THREE.HemisphereLight(0xa6b8bf,0x211810,1.1));const key=new THREE.DirectionalLight(0xffdfad,2.1);key.position.set(-4,9,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);const torch=new THREE.PointLight(0xe98939,32,12);torch.position.set(0,3,-2);scene.add(torch);const floor=new THREE.Mesh(new THREE.PlaneGeometry(14,11),makeMaterial(0x292721));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);const tileMat=makeMaterial(0x37332b);for(let x=-6;x<=6;x+=1.35)for(let z=-4.5;z<=4.5;z+=1.35){const tile=new THREE.Mesh(new THREE.BoxGeometry(1.28,.045,1.28),((Math.round(x+z)%3===0)?tileMat:makeMaterial(0x302d27)));tile.position.set(x,-.025,z);tile.receiveShadow=true;scene.add(tile)}const wallMat=makeMaterial(0x454239),rockMat=makeMaterial(0x34332e);for(const x of [-6.65,6.65]){const wall=new THREE.Mesh(new THREE.BoxGeometry(.7,4,11),wallMat);wall.position.set(x,1.7,0);wall.castShadow=true;scene.add(wall)}for(let i=0;i<8;i++){const p=new THREE.Mesh(new THREE.CylinderGeometry(.45,.58,3.8,7),rockMat);p.position.set(-5.3+i*1.5,1.7,-5.1);p.castShadow=true;scene.add(p);const cap=new THREE.Mesh(new THREE.ConeGeometry(.61,.8,7),wallMat);cap.position.set(-5.3+i*1.5,3.95,-5.1);cap.castShadow=true;scene.add(cap)}for(const side of [-1,1]){for(let z=-3;z<=3;z+=3){const p=new THREE.Mesh(new THREE.CylinderGeometry(.38,.48,2.8,7),wallMat);p.position.set(side*5.8,1.3,z);p.castShadow=true;scene.add(p)}}const brazier=new THREE.Group();const bowl=new THREE.Mesh(new THREE.CylinderGeometry(.22,.32,.3,8),makeMaterial(0x66503a));bowl.position.y=.35;brazier.add(bowl);const flame=new THREE.Mesh(new THREE.IcosahedronGeometry(.2,1),new THREE.MeshBasicMaterial({color:0xff7a20}));flame.position.y=.7;brazier.add(flame);brazier.position.set(0,0,-3.6);scene.add(brazier);playerMesh=buildFighter(0x667b55,false);playerMesh.position.set(-2.2,0,1.6);scene.add(playerMesh);enemyMesh=buildFighter(0x765447,true);enemyMesh.position.set(1.7,0,-.8);scene.add(enemyMesh);arenaReady=true;resizeArena();window.addEventListener('resize',resizeArena);const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04);if(arenaReady&&playerMesh){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dz){const n=Math.hypot(dx,dz);playerMesh.position.x=Math.max(-5,Math.min(5,playerMesh.position.x+dx/n*dt*3));playerMesh.position.z=Math.max(-3.7,Math.min(3.7,playerMesh.position.z+dz/n*dt*3));playerMesh.rotation.y=Math.atan2(dx,dz)}const dist=Math.hypot(playerMesh.position.x-enemyMesh.position.x,playerMesh.position.z-enemyMesh.position.z);$('sceneStatus').textContent=s.enemyDefeated?'Guard defeated · claim your spoils.':dist<1.65?'In range · strike now.':'Move closer to the guard.';camera.position.x+=(playerMesh.position.x*.18-camera.position.x)*dt*1.5;camera.lookAt(playerMesh.position.x*.12,.3,0);if(enemyMesh.visible)enemyMesh.rotation.y=Math.sin(performance.now()*.001)*.04}renderer.render(scene,camera)}frame()}catch(e){console.warn('3D arena could not initialize',e);$('sceneStatus').textContent='3D arena unavailable. Try a WebGL-enabled browser.'}}
 function resizeArena(){if(!renderer||!camera)return;const stage=$('threeStage'),w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}
 function helperCards(interactive){const icons={Goblin:'👺',Wizard:'🧙',Champion:'🛡️'},labels={Goblin:'Melee fighter',Wizard:'Elemental caster',Champion:'Fused champion'};return s.helpers.map(h=>`<article class="helper-card"><div class="helper-card-top"><span>${icons[h.type]||'♟'} &nbsp;${h.type}</span><b>LV ${h.level}/5</b></div><small>${labels[h.type]||'Dungeon ally'} · ${h.level>=5?'MAX LEVEL':'Ready to train'}</small><div class="helper-xp"><i style="width:${h.level*20}%"></i></div>${interactive?`<div class="helper-card-actions"><button class="btn secondary train-helper" data-helper-id="${h.id}" ${h.level>=5||s.coins<h.level*10?'disabled':''}>TRAIN · ${h.level*10} COINS</button></div>`:''}</article>`).join('')}
function render(){const r=rates();$('dayLabel').textContent=`DAY ${String(s.day).padStart(2,'0')}`;$('gold').textContent=s.gold;$('stone').textContent=s.stone;$('food').textContent=s.food;$('renown').textContent=s.renown;$('goldRate').textContent=r.gold;$('stoneRate').textContent=r.stone;$('foodRate').textContent=r.food;$('coreHp').textContent=s.hp;$('navMinions').textContent=String(s.helpers.length).padStart(2,'0');$('helperCount').textContent=`${s.helpers.length} HELPER${s.helpers.length===1?'':'S'}`;$('helperSummary').textContent=`${s.helpers.length} AJUDANTE${s.helpers.length===1?'':'S'}`;$('helperRoster').innerHTML=helperCards(false);$('helperGrid').innerHTML=helperCards(true);$('wizardBtn').disabled=s.gold<35||s.stone<15;$('wizardBtn').textContent=s.gold<35||s.stone<15?'WIZARD · NEED 35◈ 15⬟':'SUMMON WIZARD · 35◈ 15⬟';const fusionPair=s.helpers.some((a,i)=>s.helpers.slice(i+1).some(b=>a.level===5&&b.level===5&&a.type!==b.type));$('fusionBtn').disabled=!fusionPair;$('fusionBtn').textContent=fusionPair?'FUSE TWO LEVEL 5 HELPERS → CHAMPION':'FUSE DIFFERENT LVL 5 HELPERS';$('defense').textContent=strength();$('threatText').textContent=`${s.threat<35?'LOW':s.threat<70?'MODERATE':'SEVERE'} · ${s.threat}`;$('threatBar').style.width=`${Math.min(100,s.threat)}%`;$('threatHint').textContent=`Next invasion check in ${4-((s.day-1)%4)} day${4-((s.day-1)%4)===1?'':'s'}. Keep your garrison strong.`;$('rank').textContent=s.renown>=70?'DREAD SOVEREIGN':s.renown>=40?'DEPTHS TYRANT':s.renown>=20?'CAVERN LORD':'HOLLOW KEEPER';$('playerLevel').textContent=s.level;$('coins').textContent=s.coins;$('xpLabel').textContent=`${s.xp} / ${s.level*100} XP`;$('xpBar').style.width=`${Math.min(100,s.xp/(s.level*100)*100)}%`;$('enemyHp').textContent=s.enemyDefeated?'0':s.enemyHp;$('enemyBar').style.width=`${Math.max(0,s.enemyHp/40*100)}%`;$('elementDamage').textContent=`${elements[selectedElement].damage} DAMAGE`;$('elementDamage').style.color=`rgb(${elements[selectedElement].rgb})`;$('sceneObjective').innerHTML=s.enemyDefeated?'GUARD DEFEATED<br><small>Claim your spoils or advance to the next day.</small>':'DEFEAT THE CARAVAN GUARD<br><small>Choose an element, get close, and strike.</small>';if(enemyMesh)enemyMesh.visible=!s.enemyDefeated;document.querySelectorAll('.element-button').forEach(b=>b.classList.toggle('selected',b.dataset.element===selectedElement));

